<?php

// AUTO-GENERATED by /auto-improve-scaffold-tests (auth-aware) — per-route registration + gating smoke; real coverage lives in tests/Feature/Backend/.

namespace Tests\Feature\Generated;

use App\Models\User;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Symfony\Component\HttpFoundation\BinaryFileResponse;
use Tests\TestCase;

/**
 * Gating smoke: public routes (no auth required).
 *
 * - /login GET            → 200 (guest form)
 * - /register GET         → 200 (guest form)
 * - /forgot-password GET  → 200 (guest form)
 * - /reset-password/{tok} GET → 200 (guest form)
 * - / GET                 → 200 (public landing for guest)
 * - /track/open/{token}   → 200 (always returns 1×1 GIF)
 * - /u/{contact} GET      → 403 (signed URL rejected without signature)
 */
class PublicRoutesTest extends TestCase
{
    use RefreshDatabase;

    public function test_login_page_is_accessible(): void
    {
        $response = $this->get('/login');
        $response->assertStatus(200);
    }

    public function test_register_page_is_accessible(): void
    {
        $response = $this->get('/register');
        $response->assertStatus(200);
    }

    public function test_forgot_password_page_is_accessible(): void
    {
        $response = $this->get('/forgot-password');
        $response->assertStatus(200);
    }

    public function test_reset_password_page_is_accessible(): void
    {
        $response = $this->get('/reset-password/dummy-token-for-smoke-test');
        $response->assertStatus(200);
    }

    public function test_root_shows_public_landing_for_guest(): void
    {
        $response = $this->get('/');
        $landing = file_get_contents(resource_path('landing/index.html'));

        $response->assertStatus(200);

        $this->assertInstanceOf(BinaryFileResponse::class, $response->baseResponse);
        $this->assertSame(realpath(resource_path('landing/index.html')), $response->baseResponse->getFile()->getRealPath());
        $this->assertIsString($landing);
        $this->assertStringContainsString('href="/login"', $landing);
        $this->assertStringContainsString('Une prospection fret claire et maîtrisée.', $landing);
        $this->assertStringContainsString('Préparez des campagnes et séquences avant validation.', $landing);
        $this->assertStringNotContainsString('href="#"', $landing);
    }

    public function test_root_redirects_authenticated_user_to_dashboard(): void
    {
        $user = User::factory()->create();

        $this->actingAs($user)
            ->get('/')
            ->assertRedirect('/dashboard');
    }

    public function test_tracking_pixel_returns_gif_for_any_token(): void
    {
        // TrackingController::open always returns the 1×1 GIF regardless of token validity.
        $token = str_repeat('a', 64);
        $response = $this->get("/track/open/{$token}");
        $response->assertStatus(200);
    }

    public function test_unsubscribe_without_signature_returns_403(): void
    {
        // /u/{contact} is protected by Laravel signed URL middleware.
        // Without a valid signature the middleware returns 403 (InvalidSignatureException).
        $response = $this->get('/u/1');
        $response->assertStatus(403);
    }
}
